import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF -- enumerated source for the Azure Well-Architected SaaS workload assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-saas-checklist.md","filePath":"frameworks/waf-saas-checklist.md"}'),s={name:"frameworks/waf-saas-checklist.md"};function o(n,t,i,c,l,u){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="waf-enumerated-source-for-the-azure-well-architected-saas-workload-assessment" tabindex="-1">WAF -- enumerated source for the Azure Well-Architected SaaS workload assessment <a class="header-anchor" href="#waf-enumerated-source-for-the-azure-well-architected-saas-workload-assessment" aria-label="Permalink to &quot;WAF -- enumerated source for the Azure Well-Architected SaaS workload assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below -- read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.saas.yaml</code> scores the review in Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/d349c8c3-fe9c-4829-afdd-a5228e72a570/" target="_blank" rel="noreferrer">Azure Well-Architected SaaS workload</a> assessment, which independent software vendors use to check a SaaS workload against the Well-Architected Framework. <code>src/assess/rules/waf.saas.yaml</code> is written against this page only, and every rule cites an item number from the tables below. Most items are organisational, so they are <strong>manual</strong> questions answered with <code>-AssessmentAnswers</code>; a few are <strong>automated</strong> from collected Azure data.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/d349c8c3-fe9c-4829-afdd-a5228e72a570/" target="_blank" rel="noreferrer">Azure Well-Architected SaaS workload</a> (question text not published)</td></tr><tr><td>Framework version</td><td>Azure Well-Architected SaaS workload guidance on Microsoft Learn, current as of the extraction date (no published version number)</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Each source page below was fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Every property an automated item reads was checked against the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code>.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published. The items below are <strong>Scout-derived</strong>: Scout&#39;s reading of the design considerations and design recommendations in each SaaS design-area article, restated as questions. The <code>SAAS-*</code> IDs are Scout&#39;s own. A Scout score is a measure of how many of Scout&#39;s items are met; it is not the score the Microsoft assessment would give.</p><p>Sources:</p><ul><li>[ASM] <a href="https://learn.microsoft.com/azure/well-architected/saas/assessment" target="_blank" rel="noreferrer">Assessment review tool for SaaS workloads on Azure</a></li><li>[BCM] <a href="https://learn.microsoft.com/azure/well-architected/saas/billing-cost-management" target="_blank" rel="noreferrer">Billing and cost management for SaaS workloads</a></li><li>[GOV] <a href="https://learn.microsoft.com/azure/well-architected/saas/governance" target="_blank" rel="noreferrer">Governance for SaaS workloads</a></li><li>[RO] <a href="https://learn.microsoft.com/azure/well-architected/saas/resource-organization" target="_blank" rel="noreferrer">Resource organization for SaaS workloads</a></li><li>[IAM] <a href="https://learn.microsoft.com/azure/well-architected/saas/identity-access" target="_blank" rel="noreferrer">Identity and access management for SaaS workloads</a></li><li>[CMP] <a href="https://learn.microsoft.com/azure/well-architected/saas/compute" target="_blank" rel="noreferrer">Compute for SaaS workloads</a></li><li>[NET] <a href="https://learn.microsoft.com/azure/well-architected/saas/networking" target="_blank" rel="noreferrer">Networking for SaaS workloads</a></li><li>[DAT] <a href="https://learn.microsoft.com/azure/well-architected/saas/data" target="_blank" rel="noreferrer">Data for SaaS workloads</a></li><li>[DEV] <a href="https://learn.microsoft.com/azure/well-architected/saas/devops" target="_blank" rel="noreferrer">DevOps practices for SaaS workloads</a></li><li>[INC] <a href="https://learn.microsoft.com/azure/well-architected/saas/incident-management" target="_blank" rel="noreferrer">Incident management for SaaS workloads</a></li><li>[AIS] <a href="https://learn.microsoft.com/azure/well-architected/saas/ai-strategy" target="_blank" rel="noreferrer">Build an AI Strategy for your SaaS Business</a></li></ul><p>Automated items are <strong>gated</strong>: they run only when the resources they judge exist, so an estate without them reports those items Not assessed rather than passed or failed. Manual items are answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>); where collected Azure data bears on the question it is attached to the item as evidence.</p><h2 id="the-enumeration-108-items-across-10-design-areas" tabindex="-1">The enumeration -- 108 items across 10 design areas <a class="header-anchor" href="#the-enumeration-108-items-across-10-design-areas" aria-label="Permalink to &quot;The enumeration -- 108 items across 10 design areas&quot;">​</a></h2><h3 id="billing-and-cost-management-bc-10-items" tabindex="-1">Billing and cost management (BC) -- 10 items <a class="header-anchor" href="#billing-and-cost-management-bc-10-items" aria-label="Permalink to &quot;Billing and cost management (BC) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-BC-01</td><td>Billing meters are meaningful to customers</td><td>Manual</td><td>BCM</td></tr><tr><td>SAAS-BC-02</td><td>Billing tiers and SKUs are defined systematically, not per customer</td><td>Manual</td><td>BCM</td></tr><tr><td>SAAS-BC-03</td><td>Billing is aligned with cost of goods sold</td><td>Manual</td><td>BCM</td></tr><tr><td>SAAS-BC-04</td><td>A cost model covers marginal cost per customer and scale points</td><td>Manual</td><td>BCM</td></tr><tr><td>SAAS-BC-05</td><td>Budgets guard against overspend</td><td>Automated -- <code>governance.budgets</code></td><td>BCM</td></tr><tr><td>SAAS-BC-06</td><td>Cost is attributable to customers through tags or customer-specific resource groups</td><td>Manual -- <code>tags</code> attached as evidence</td><td>BCM</td></tr><tr><td>SAAS-BC-07</td><td>Azure billing constructs are used to lower cost of goods sold</td><td>Manual -- <code>finops.reservations</code> attached as evidence</td><td>BCM</td></tr><tr><td>SAAS-BC-08</td><td>Unused resources are removed and utilisation is reviewed with Azure Advisor</td><td>Manual -- <code>costCleanup.orphanedDisks</code> attached as evidence</td><td>BCM</td></tr><tr><td>SAAS-BC-09</td><td>Service quotas and limits are understood before scale points are reached</td><td>Manual</td><td>BCM, RO</td></tr><tr><td>SAAS-BC-10</td><td>Azure Marketplace publishing has been considered</td><td>Manual</td><td>BCM, RO</td></tr></tbody></table><h3 id="governance-and-compliance-gv-10-items" tabindex="-1">Governance and compliance (GV) -- 10 items <a class="header-anchor" href="#governance-and-compliance-gv-10-items" aria-label="Permalink to &quot;Governance and compliance (GV) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-GV-01</td><td>A naming convention and tagging strategy identify workload, environment and customer</td><td>Manual -- <code>tags</code> attached as evidence</td><td>GOV</td></tr><tr><td>SAAS-GV-02</td><td>Azure Policy assignments enforce standards</td><td>Automated -- <code>governance.policyAssignments</code></td><td>GOV</td></tr><tr><td>SAAS-GV-03</td><td>Resource locks protect critical resources</td><td>Automated -- <code>governance.resourceLocks</code></td><td>GOV</td></tr><tr><td>SAAS-GV-04</td><td>Defender for Cloud assesses compliance against a security baseline (Defender CSPM)</td><td>Automated -- <code>security.defenderPlans</code></td><td>GOV</td></tr><tr><td>SAAS-GV-05</td><td>Access is least privilege, with privileged assignments and subscription owners limited</td><td>Manual</td><td>GOV</td></tr><tr><td>SAAS-GV-06</td><td>Roles are assigned to groups rather than to individual users</td><td>Manual -- <code>governance.roleAssignments</code> attached as evidence</td><td>GOV</td></tr><tr><td>SAAS-GV-07</td><td>A security baseline is adopted early in the design</td><td>Manual</td><td>GOV</td></tr><tr><td>SAAS-GV-08</td><td>The Microsoft Entra tenant strategy is deliberate</td><td>Manual</td><td>GOV</td></tr><tr><td>SAAS-GV-09</td><td>Customer compliance obligations are identified and evidenced</td><td>Manual</td><td>GOV, NET</td></tr><tr><td>SAAS-GV-10</td><td>Cost Management and cost alerts are enabled</td><td>Manual -- <code>finops.anomalies</code> attached as evidence</td><td>GOV, BCM</td></tr></tbody></table><h3 id="resource-organization-ro-7-items" tabindex="-1">Resource organization (RO) -- 7 items <a class="header-anchor" href="#resource-organization-ro-7-items" aria-label="Permalink to &quot;Resource organization (RO) -- 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-RO-01</td><td>Regions are chosen for availability zones, service availability and data residency</td><td>Manual</td><td>RO</td></tr><tr><td>SAAS-RO-02</td><td>The number of regions is the minimum that meets requirements</td><td>Manual</td><td>RO</td></tr><tr><td>SAAS-RO-03</td><td>The split between shared and per-customer resources is decided and documented</td><td>Manual</td><td>RO</td></tr><tr><td>SAAS-RO-04</td><td>Pre-production does not use shared production resources</td><td>Manual</td><td>RO</td></tr><tr><td>SAAS-RO-05</td><td>The Deployment Stamps pattern is considered for scale and isolation</td><td>Manual</td><td>RO, CMP</td></tr><tr><td>SAAS-RO-06</td><td>Resource lifetimes and lifecycles are defined</td><td>Manual -- <code>tags</code> attached as evidence</td><td>RO</td></tr><tr><td>SAAS-RO-07</td><td>The landing zone follows ISV guidance</td><td>Manual</td><td>RO</td></tr></tbody></table><h3 id="identity-and-access-management-id-10-items" tabindex="-1">Identity and access management (ID) -- 10 items <a class="header-anchor" href="#identity-and-access-management-id-10-items" aria-label="Permalink to &quot;Identity and access management (ID) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-ID-01</td><td>The tenancy and deployment model drive the identity design</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-02</td><td>Each user has one account, with access granted per tenant</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-03</td><td>Identity requirements and a provider capability matrix are documented</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-04</td><td>An identity-as-a-service provider is used, not a self-built one</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-05</td><td>Federated sign-in is planned, with onboarding automated and priced</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-06</td><td>Cross-tenant data access is blocked unless explicitly permitted</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-07</td><td>The authorization model and the store for authorization data are chosen deliberately</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-08</td><td>Customers manage permissions for their own users</td><td>Manual</td><td>IAM</td></tr><tr><td>SAAS-ID-09</td><td>Workloads authenticate with managed identities, not stored credentials</td><td>Manual -- <code>domains.identity.managedIdentities</code> attached as evidence</td><td>IAM, DAT</td></tr><tr><td>SAAS-ID-10</td><td>Data residency for identity data is planned</td><td>Manual</td><td>IAM</td></tr></tbody></table><h3 id="compute-cp-10-items" tabindex="-1">Compute (CP) -- 10 items <a class="header-anchor" href="#compute-cp-10-items" aria-label="Permalink to &quot;Compute (CP) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-CP-01</td><td>The compute platform fits requirements and starts with the least complex option the team knows</td><td>Manual</td><td>CMP</td></tr><tr><td>SAAS-CP-02</td><td>Compute needs are modelled and load tested</td><td>Manual</td><td>CMP</td></tr><tr><td>SAAS-CP-03</td><td>Tenant isolation is enforced in the compute platform and in the application</td><td>Manual</td><td>CMP</td></tr><tr><td>SAAS-CP-04</td><td>Resource consumption is monitored per customer to catch noisy neighbours</td><td>Manual</td><td>CMP</td></tr><tr><td>SAAS-CP-05</td><td>Autoscale settings are enabled</td><td>Automated -- <code>monitor.autoscaleSettings</code></td><td>CMP</td></tr><tr><td>SAAS-CP-06</td><td>Workloads scale horizontally and are stateless where possible</td><td>Manual</td><td>CMP</td></tr><tr><td>SAAS-CP-07</td><td>A scaling threshold for deploying a new stamp is defined</td><td>Manual</td><td>CMP</td></tr><tr><td>SAAS-CP-08</td><td>Virtual machines are deployed across availability zones where the region has them</td><td>Automated -- <code>compute.virtualMachines</code></td><td>CMP</td></tr><tr><td>SAAS-CP-09</td><td>AKS node pools span availability zones</td><td>Automated -- <code>domains.containers.aksClusters</code></td><td>CMP</td></tr><tr><td>SAAS-CP-10</td><td>Reliability targets are defined and failure modes are tested</td><td>Manual</td><td>CMP</td></tr></tbody></table><h3 id="networking-nw-10-items" tabindex="-1">Networking (NW) -- 10 items <a class="header-anchor" href="#networking-nw-10-items" aria-label="Permalink to &quot;Networking (NW) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-NW-01</td><td>The network topology matches the tenancy model</td><td>Manual</td><td>NET</td></tr><tr><td>SAAS-NW-02</td><td>A catalogue of internet-exposed endpoints exists, with protection decided for each</td><td>Manual -- <code>networking.nsgPublicInbound</code> attached as evidence</td><td>NET</td></tr><tr><td>SAAS-NW-03</td><td>Web front ends sit behind a reverse proxy with a web application firewall</td><td>Automated -- <code>networking.applicationGateways</code></td><td>NET</td></tr><tr><td>SAAS-NW-04</td><td>Internet-facing endpoints are protected against DDoS attacks</td><td>Manual -- <code>security.ddosProtectionPlans</code> attached as evidence</td><td>NET</td></tr><tr><td>SAAS-NW-05</td><td>Storage accounts deny network access by default</td><td>Automated -- <code>domains.storage.storageAccounts</code></td><td>NET, DAT</td></tr><tr><td>SAAS-NW-06</td><td>Internal traffic uses private connectivity</td><td>Manual -- <code>networking.privateEndpoints</code> attached as evidence</td><td>NET</td></tr><tr><td>SAAS-NW-07</td><td>Outbound traffic is controlled and SNAT capacity is planned</td><td>Manual -- <code>networking.natGateways</code> attached as evidence</td><td>NET</td></tr><tr><td>SAAS-NW-08</td><td>Cross-network connectivity prefers private paths and IP ranges are planned</td><td>Manual</td><td>NET</td></tr><tr><td>SAAS-NW-09</td><td>Customer-hosted deployments use Azure Managed Applications</td><td>Manual -- <code>management.managedApplications</code> attached as evidence</td><td>NET, DEV</td></tr><tr><td>SAAS-NW-10</td><td>Public access is disabled by default on Azure resources</td><td>Manual -- <code>domains.storage.storageAccounts</code> attached as evidence</td><td>NET</td></tr></tbody></table><h3 id="data-dt-14-items" tabindex="-1">Data (DT) -- 14 items <a class="header-anchor" href="#data-dt-14-items" aria-label="Permalink to &quot;Data (DT) -- 14 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-DT-01</td><td>Transactional and analytical data stores are separate</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-02</td><td>The number of data store types is minimised and managed services are preferred</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-03</td><td>Database segmentation per customer is decided</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-04</td><td>Data stores are deployed in the same region as the application</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-05</td><td>Customer-defined data uses a standard design, not per-customer schema changes</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-06</td><td>Capacity is modelled per customer size</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-07</td><td>Reliability targets for data are quantified and zone-redundant stores are used</td><td>Manual -- <code>domains.databases.sqlDatabases</code> attached as evidence</td><td>DAT</td></tr><tr><td>SAAS-DT-08</td><td>Backups are kept in a geo-redundant form and recovery is tested</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-09</td><td>SQL servers have public network access disabled</td><td>Automated -- <code>domains.databases.sqlServers</code></td><td>DAT</td></tr><tr><td>SAAS-DT-10</td><td>Cosmos DB accounts have public network access disabled</td><td>Automated -- <code>domains.databases.cosmosDbAccounts</code></td><td>DAT</td></tr><tr><td>SAAS-DT-11</td><td>Cosmos DB accounts do not rely on account keys</td><td>Automated -- <code>domains.databases.cosmosDbAccounts</code></td><td>DAT</td></tr><tr><td>SAAS-DT-12</td><td>A data retention strategy is planned and enforced</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-13</td><td>Requests on shared data stores are scoped to a single tenant</td><td>Manual</td><td>DAT</td></tr><tr><td>SAAS-DT-14</td><td>Customers do not get direct access to production data stores</td><td>Manual</td><td>DAT</td></tr></tbody></table><h3 id="deployment-devops-practices-do-12-items" tabindex="-1">Deployment (DevOps) practices (DO) -- 12 items <a class="header-anchor" href="#deployment-devops-practices-do-12-items" aria-label="Permalink to &quot;Deployment (DevOps) practices (DO) -- 12 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-DO-01</td><td>Each customer lifecycle event is documented and automated where practical</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-02</td><td>Infrastructure is deployed as code</td><td>Manual -- <code>management.deployments</code> attached as evidence</td><td>DEV</td></tr><tr><td>SAAS-DO-03</td><td>Core infrastructure is separated from customer-level infrastructure</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-04</td><td>Customers are mapped to the infrastructure that serves them</td><td>Manual -- <code>tags</code> attached as evidence</td><td>DEV</td></tr><tr><td>SAAS-DO-05</td><td>Updates roll out progressively using safe deployment practices</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-06</td><td>Configuration is treated as code and deployed with the same rigor</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-07</td><td>A version and change-management policy is communicated to customers</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-08</td><td>The product is not customised per customer</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-09</td><td>A rollback plan exists for failed deployments</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-10</td><td>Testing runs at several stages</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-11</td><td>Customers are told about upcoming and completed deployments</td><td>Manual</td><td>DEV</td></tr><tr><td>SAAS-DO-12</td><td>Established DevOps tooling is used instead of custom tooling</td><td>Manual</td><td>DEV</td></tr></tbody></table><h3 id="incident-management-im-13-items" tabindex="-1">Incident management (IM) -- 13 items <a class="header-anchor" href="#incident-management-im-13-items" aria-label="Permalink to &quot;Incident management (IM) -- 13 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-IM-01</td><td>The organisation accepts 24x7 live-site responsibility with a staffed on-call rotation</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-02</td><td>A frontline support team handles cases and escalates to engineering</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-03</td><td>Incident tooling covers monitoring, escalation and controlled production change</td><td>Manual -- <code>monitor.actionGroups</code> attached as evidence</td><td>INC</td></tr><tr><td>SAAS-IM-04</td><td>Azure Monitor action groups are enabled</td><td>Automated -- <code>monitor.actionGroups</code></td><td>INC</td></tr><tr><td>SAAS-IM-05</td><td>Severity levels and an escalation path are defined</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-06</td><td>Architecture, owners and key contacts are documented for triage</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-07</td><td>Responders can reach logs and make controlled production changes</td><td>Manual -- <code>management.logAnalyticsWorkspaces</code> attached as evidence</td><td>INC</td></tr><tr><td>SAAS-IM-08</td><td>A commercial status page and a communications manager keep customers informed</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-09</td><td>Recovery is prioritised over diagnosis during an incident</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-10</td><td>Internal post-incident reviews track remediation with clear accountability</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-11</td><td>Customer-facing post-incident reviews are published</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-12</td><td>A mission-critical support plan exists with platform vendors</td><td>Manual</td><td>INC</td></tr><tr><td>SAAS-IM-13</td><td>Alert rules cover availability and performance of the service</td><td>Manual -- <code>monitor.metricAlertRules</code> attached as evidence</td><td>INC</td></tr></tbody></table><h3 id="ai-strategy-for-saas-ai-12-items" tabindex="-1">AI strategy for SaaS (AI) -- 12 items <a class="header-anchor" href="#ai-strategy-for-saas-ai-12-items" aria-label="Permalink to &quot;AI strategy for SaaS (AI) -- 12 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>SAAS-AI-01</td><td>AI strategy is set at leadership level with a clear vision and principles</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-02</td><td>A named owner or working group is accountable for AI initiatives</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-03</td><td>A shared inventory of AI use cases separates foundational, conversational, agentic and multi-agent uses</td><td>Manual -- <code>domains.ai.cognitiveAccounts</code> attached as evidence</td><td>AIS</td></tr><tr><td>SAAS-AI-04</td><td>The AI strategy is communicated and teams are trained in AI</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-05</td><td>AI initiatives map to measurable business outcomes</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-06</td><td>Humans stay in the loop for critical judgments</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-07</td><td>AI governance defines the model lifecycle</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-08</td><td>Build, buy or customise is decided for each AI capability</td><td>Manual -- <code>domains.ai.mlWorkspaces</code> attached as evidence</td><td>AIS</td></tr><tr><td>SAAS-AI-09</td><td>GenAIOps practices are part of DevOps and CI/CD</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-10</td><td>Responsible AI principles are embedded in foundational practices</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-11</td><td>Shared models are not trained on raw customer data without explicit permission</td><td>Manual</td><td>AIS</td></tr><tr><td>SAAS-AI-12</td><td>The product can be used by AI agents through APIs</td><td>Manual</td><td>AIS</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Billing and cost management</td><td>10</td><td>1</td><td>9</td></tr><tr><td>Governance and compliance</td><td>10</td><td>3</td><td>7</td></tr><tr><td>Resource organization</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Identity and access management</td><td>10</td><td>0</td><td>10</td></tr><tr><td>Compute</td><td>10</td><td>3</td><td>7</td></tr><tr><td>Networking</td><td>10</td><td>2</td><td>8</td></tr><tr><td>Data</td><td>14</td><td>3</td><td>11</td></tr><tr><td>Deployment (DevOps) practices</td><td>12</td><td>0</td><td>12</td></tr><tr><td>Incident management</td><td>13</td><td>1</td><td>12</td></tr><tr><td>AI strategy for SaaS</td><td>12</td><td>0</td><td>12</td></tr><tr><td><strong>Total</strong></td><td><strong>108</strong></td><td><strong>13</strong></td><td><strong>95</strong></td></tr></tbody></table><p>The AI strategy items come from the SaaS &quot;AI strategy&quot; article; the resource organization items from the &quot;Resource organization&quot; article, which the assessment page lists among the design areas. Design methodology and design principles pages are not enumerated: they describe how to apply the design areas rather than adding checks of their own.</p>',34)])])}const A=e(s,[["render",o]]);export{m as __pageData,A as default};
